<script>
import * as echarts from 'echarts'
import axios from 'axios'
import AddOrUpdate from "./add-or-update";

export default {
  data() {
    return {
      searchForm: {
        key: ""
      },
      form: {},
      dataList: [],
      pageIndex: 1,
      pageSize: 10,
      totalPage: 0,
      dataListLoading: false,
      dataListSelections: [],
      showFlag: true,
      sfshVisiable: false,
      shForm: {},
      chartVisiable: false,
      chartVisiable1: false,
      chartVisiable2: false,
      chartVisiable3: false,
      chartVisiable4: false,
      chartVisiable5: false,
      addOrUpdateFlag: false,
      layouts: ["total", "prev", "pager", "next", "sizes", "jumper"],

    };
  },
  created() {
    this.init();
    this.getDataList();
    this.contentStyleChange()
  },
  mounted() {
  },
  filters: {
    htmlfilter: function (val) {
      return val.replace(/<[^>]*>/g).replace(/undefined/g, '');
    }
  },
  components: {
    AddOrUpdate,
  },
  methods: {

    contentStyleChange() {
      this.contentPageStyleChange()
    },
    // 分页
    contentPageStyleChange() {
      let arr = []

      // if(this.contents.pageTotal) arr.push('total')
      // if(this.contents.pageSizes) arr.push('sizes')
      // if(this.contents.pagePrevNext){
      //   arr.push('prev')
      //   if(this.contents.pagePager) arr.push('pager')
      //   arr.push('next')
      // }
      // if(this.contents.pageJumper) arr.push('jumper')
      // this.layouts = arr.join()
      // this.contents.pageEachNum = 10
    },


//统计接口
    chartDialog1() {
      this.chartVisiable1 = !this.chartVisiable1;
      this.$nextTick(() => {

        var shangpinfenleiChart1 = echarts.init(document.getElementById("shangpinfenleiChart1"), 'macarons');
        this.$http({
          url: "shangpinxinxi/group/shangpinfenlei",
          method: "get",
        }).then(({data}) => {
          if (data && data.code === 0) {
            let res = data.data;
            let xAxis = [];
            let yAxis = [];
            let pArray = []
            for (let i = 0; i < res.length; i++) {
              xAxis.push(res[i].shangpinfenlei);
              yAxis.push(parseFloat((res[i].total)));
              pArray.push({
                value: parseFloat((res[i].total)),
                name: res[i].shangpinfenlei
              })
            }
            var option = {};
            option = {
              title: {
                text: '商品分类统计',
                left: 'center'
              },
              legend: {
                orient: 'vertical',
                left: 'left'
              },
              tooltip: {
                trigger: 'item',
                formatter: '{b} : {c} ({d}%)'
              },
              series: [
                {
                  type: 'pie',
                  radius: ['25%', '55%'],
                  center: ['50%', '60%'],
                  data: pArray,
                  emphasis: {
                    itemStyle: {
                      shadowBlur: 10,
                      shadowOffsetX: 0,
                      shadowColor: 'rgba(0, 0, 0, 0.5)'
                    }
                  }
                }
              ]
            };
            // 使用刚指定的配置项和数据显示图表。
            shangpinfenleiChart1.setOption(option);
            //根据窗口的大小变动图表
            window.onresize = function () {
              shangpinfenleiChart1.resize();
            };
          }
        });
      })
    },

//统计接口
    chartDialog2() {
      this.chartVisiable2 = !this.chartVisiable2;
      this.$nextTick(() => {
        // shangpinmingcheng shangpinmingcheng
        //  alllimittimes

        var alllimittimesChart2 = echarts.init(document.getElementById("alllimittimesChart2"), 'macarons');
        this.$http({
          url: `shangpinxinxi/value/shangpinmingcheng/alllimittimes`,
          method: "get",
        }).then(({data}) => {
          if (data && data.code === 0) {
            let res = data.data;
            let xAxis = [];
            let yAxis = [];
            let pArray = []
            for (let i = 0; i < res.length; i++) {
              xAxis.push(res[i].shangpinmingcheng);
              yAxis.push(parseFloat((res[i].total)));
              pArray.push({
                value: parseFloat((res[i].total)),
                name: res[i].shangpinmingcheng
              })
            }
            var option = {};
            option = {
              title: {
                text: '商品库存统计',
                left: 'center'
              },
              tooltip: {
                trigger: 'item',
                formatter: '{b} : {c}'
              },
              xAxis: {
                type: 'category',
                data: xAxis
              },
              yAxis: {
                type: 'value'
              },
              series: [{
                data: yAxis,
                type: 'bar'
              }]
            };
            // 使用刚指定的配置项和数据显示图表。
            alllimittimesChart2.setOption(option);
            //根据窗口的大小变动图表
            window.onresize = function () {
              alllimittimesChart2.resize();
            };
          }
        });
      })
    },


    init() {
    },
    search() {
      this.pageIndex = 1;
      this.getDataList();
    },

    // 获取数据列表
    getDataList() {
      this.dataListLoading = true;
      let params = {
        page: this.pageIndex,
        limit: this.pageSize,
        sort: 'id',
        order: 'desc',
      }
      if (this.searchForm.shangpinmingcheng != '' && this.searchForm.shangpinmingcheng != undefined) {
        params['shangpinmingcheng'] = '%' + this.searchForm.shangpinmingcheng + '%'
      }
      if (this.searchForm.chandi != '' && this.searchForm.chandi != undefined) {
        params['chandi'] = '%' + this.searchForm.chandi + '%'
      }
      if (this.searchForm.pinpai != '' && this.searchForm.pinpai != undefined) {
        params['pinpai'] = '%' + this.searchForm.pinpai + '%'
      }
      this.$http({
        url: "shangpinxinxi/page",
        method: "get",
        params: params
      }).then(({data}) => {
        if (data && data.code === 0) {
          this.dataList = data.data.list;
          this.totalPage = data.data.total;
        } else {
          this.dataList = [];
          this.totalPage = 0;
        }
        this.dataListLoading = false;
      });
    },
    // 每页数
    sizeChangeHandle(val) {
      this.pageSize = val;
      this.pageIndex = 1;
      this.getDataList();
    },
    // 当前页
    currentChangeHandle(val) {
      this.pageIndex = val;
      this.getDataList();
    },
    // 多选
    selectionChangeHandler(val) {
      this.dataListSelections = val;
    },
    // 添加/修改
    addOrUpdateHandler(id, type) {
      this.showFlag = false;
      this.addOrUpdateFlag = true;
      this.crossAddOrUpdateFlag = false;
      if (type != 'info') {
        type = 'else';
      }
      this.$nextTick(() => {
        this.$refs.addOrUpdate.init(id, type);
      });
    },
    // 查看评论
    disscussListHandler(id, type) {
      this.$router.push({path: '/discussshangpinxinxi', query: {refid: id}});
    },
    // 下载
    download(file) {
      window.open(`${file}`)
    },
    // 删除
    deleteHandler(id) {
      var ids = id
          ? [Number(id)]
          : this.dataListSelections.map(item => {
            return Number(item.id);
          });
      this.$confirm(`确定进行[${id ? "删除" : "批量删除"}]操作?`, "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      }).then(() => {
        this.$http({
          url: "shangpinxinxi/delete",
          method: "post",
          data: ids
        }).then(({data}) => {
          if (data && data.code === 0) {
            this.$message({
              message: "操作成功",
              type: "success",
              duration: 1500,
              onClose: () => {
                this.search();
              }
            });
          } else {
            this.$message.error(data.msg);
          }
        });
      });
    },


  }

};
</script>
